package com.mirigangneung.composition.service;import com.mirigangneung.composition.repository.CompositionJobRepository;import com.mirigangneung.infrastructure.storage.TemporaryImageStorage;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import java.time.*;@Component public class CompositionCleanupJob{private final CompositionJobRepository jobs;private final TemporaryImageStorage storage;public CompositionCleanupJob(CompositionJobRepository j,TemporaryImageStorage s){jobs=j;storage=s;}@Scheduled(fixedDelayString="${IMAGE_CLEANUP_DELAY_MS:3600000}")public void cleanup(){jobs.findByExpiresAtBefore(OffsetDateTime.now()).forEach(j->{try{storage.delete(j.getInputStorageKey());}catch(Exception ignored){}jobs.delete(j);});}}
